/**
 * Canonical Source Registry for EventPulse
 * 
 * This is the SINGLE SOURCE OF TRUTH for source identification.
 * All source normalization, labeling, and mapping happens here.
 * 
 * DO NOT add source logic anywhere else.
 */

// Canonical source definitions
// Key = canonical source ID (kebab-case or lowercase)
// Value = { label: display name, type: 'aggregator' | 'venue' | 'curated' }
const CANONICAL_SOURCES = {
  'ticketmaster': {
    label: 'Ticketmaster',
    type: 'aggregator',
  },
  'stockholm': {
    label: 'Stockholm',
    type: 'curated',
  },
  'kulturhuset': {
    label: 'Kulturhuset',
    type: 'venue',
  },
  'kulturhuset-barn-ung': {
    label: 'Kulturhuset Barn & Ung',
    type: 'venue',
  },
  'malmo-live': {
    label: 'Malmö Live',
    type: 'venue',
  },
  'debaser': {
    label: 'Debaser',
    type: 'venue',
  },
  'tele2-arena': {
    label: 'Tele2 Arena',
    type: 'venue',
  },
  'friends-arena': {
    label: 'Friends Arena',
    type: 'venue',
  },
  'avicii-arena': {
    label: 'Avicii Arena',
    type: 'venue',
  },
  'fotografiska': {
    label: 'Fotografiska',
    type: 'venue',
  },
  'berwaldhallen': {
    label: 'Berwaldhallen',
    type: 'venue',
  },
  'malmo-opera': {
    label: 'Malmö Opera',
    type: 'venue',
  },
  'sodra-teatern': {
    label: 'Södra Teatern',
    type: 'venue',
  },
  'annexet': {
    label: 'Annexet',
    type: 'venue',
  },
  'slakthuset': {
    label: 'Slakthuset',
    type: 'venue',
  },
  'fryshuset': {
    label: 'Fryshuset',
    type: 'venue',
  },
  'eventpulse': {
    label: 'EventPulse',
    type: 'aggregator',
  },
};

// Source aliases for normalization
// Maps legacy/variant names to canonical keys
const SOURCE_ALIAS_MAP = {
  // Malmö Live variations
  'malmolive': 'malmo-live',
  'malmo_live': 'malmo-live',
  'stockholmlive': 'malmo-live',
  // Other known variations
  'ticket master': 'ticketmaster',
  'ticket-master': 'ticketmaster',
};

/**
 * Normalize a source string to canonical key
 * @param {string} source - Raw source string
 * @returns {string} Canonical source key
 */
function normalizeSource(source) {
  if (!source) return 'unknown';
  const normalized = source.toLowerCase().trim();
  return SOURCE_ALIAS_MAP[normalized] || normalized;
}

/**
 * Check if a source key is canonical (known)
 * @param {string} source - Source key
 * @returns {boolean}
 */
function isCanonicalSource(source) {
  return CANONICAL_SOURCES.hasOwnProperty(source);
}

/**
 * Get metadata for a canonical source
 * @param {string} source - Source key
 * @returns {{ label: string, type: string } | null}
 */
function getSourceMetadata(source) {
  return CANONICAL_SOURCES[source] || null;
}

/**
 * Get all canonical sources as array for dropdown
 * @returns {Array<{ key: string, label: string, type: string }>}
 */
function getAllSources() {
  return Object.entries(CANONICAL_SOURCES).map(([key, meta]) => ({
    key,
    label: meta.label,
    type: meta.type,
  }));
}

/**
 * Filter sources to only known canonical ones
 * @param {string[]} sources - Array of source keys
 * @returns {Array<{ key: string, label: string, type: string }>}
 */
function filterCanonicalSources(sources) {
  return sources
    .filter(key => CANONICAL_SOURCES[key])
    .map(key => ({
      key,
      label: CANONICAL_SOURCES[key].label,
      type: CANONICAL_SOURCES[key].type,
    }));
}

/**
 * Validate event has required fields (unified shape)
 * @param {Object} event - Event object
 * @returns {{ valid: boolean, missing: string[] }}
 */
function validateEventShape(event) {
  const required = ['id', 'title', 'source', 'city', 'date'];
  const missing = required.filter(field => {
    const value = event[field];
    return value === undefined || value === null || value === '';
  });
  return {
    valid: missing.length === 0,
    missing,
  };
}

module.exports = {
  CANONICAL_SOURCES,
  SOURCE_ALIAS_MAP,
  normalizeSource,
  isCanonicalSource,
  getSourceMetadata,
  getAllSources,
  filterCanonicalSources,
  validateEventShape,
};
